@using sv_56351d07ae4346c88467476796cef921.Models

<div class="step-indicator">
    @for (int i = 1; i <= 5; i++)
    {
        var step = i;
        var label = step switch
        {
            1 => "Personal Info",
            2 => "Work History",
            3 => "References",
            4 => "Cover Letter",
            5 => "Review & Submit",
            _ => ""
        };

        var cssClass = "step";
        if (step == CurrentStep) cssClass += " active";
        else if (CompletedSteps.Contains(step)) cssClass += " completed";
        else cssClass += " future";

        <div class="@cssClass" @onclick="() => HandleClick(step)">
            <div class="step-circle">
                @if (CompletedSteps.Contains(step) && step != CurrentStep)
                {
                    <span>✓</span>
                }
                else
                {
                    <span>@step</span>
                }
            </div>
            <div class="step-label">@label</div>
        </div>
    }
</div>

@code {
    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }

    private async Task HandleClick(int step)
    {
        if (CompletedSteps.Contains(step))
        {
            await OnStepClicked.InvokeAsync(step);
        }
    }
}

@using sv_56351d07ae4346c88467476796cef921.Models

<div class="work-entry-card">
    <div class="card-header">
        <h4>Position @(Index + 1)</h4>
        @if (CanRemove)
        {
            <button type="button" class="btn-remove" @onclick="() => OnRemove.InvokeAsync(Index)">Remove</button>
        }
    </div>

    <div class="form-group">
        <label>Company</label>
        <input type="text" value="@Entry.Company" @onchange="e => Update(company: e.Value?.ToString())" />
    </div>

    <div class="form-group">
        <label>Title</label>
        <input type="text" value="@Entry.Title" @onchange="e => Update(title: e.Value?.ToString())" />
    </div>

    <div class="form-group">
        <label>Start Date</label>
        <input type="date" value="@Entry.StartDate.ToString("yyyy-MM-dd")" @onchange="e => Update(startDate: DateTime.TryParse(e.Value?.ToString(), out var d) ? d : Entry.StartDate)" />
    </div>

    <div class="form-group">
        <label>
            <input type="checkbox" checked="@isCurrent" @onchange="HandleCurrentChanged" />
            I currently work here
        </label>
    </div>

    @if (!isCurrent)
    {
        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@(Entry.EndDate?.ToString("yyyy-MM-dd") ?? "")" @onchange="e => Update(endDate: DateTime.TryParse(e.Value?.ToString(), out var d) ? d : Entry.EndDate)" />
        </div>
    }

    <div class="form-group">
        <label>Description</label>
        <textarea value="@Entry.Description" @onchange="e => Update(description: e.Value?.ToString())"></textarea>
    </div>
</div>

@code {
    [Parameter] public WorkEntry Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<int> OnRemove { get; set; }
    [Parameter] public EventCallback<(int, WorkEntry)> OnChanged { get; set; }

    private bool isCurrent => Entry.EndDate == null;

    private async Task HandleCurrentChanged(ChangeEventArgs e)
    {
        var isChecked = (bool)(e.Value ?? false);
        if (isChecked)
        {
            await OnChanged.InvokeAsync((Index, Entry with { EndDate = null }));
        }
        else
        {
            await OnChanged.InvokeAsync((Index, Entry with { EndDate = DateTime.Today }));
        }
    }

    private async Task Update(string? company = null, string? title = null, DateTime? startDate = null, DateTime? endDate = null, string? description = null)
    {
        var updated = Entry with
        {
            Company = company ?? Entry.Company,
            Title = title ?? Entry.Title,
            StartDate = startDate ?? Entry.StartDate,
            EndDate = endDate ?? Entry.EndDate,
            Description = description ?? Entry.Description
        };
        await OnChanged.InvokeAsync((Index, updated));
    }
}

@using sv_56351d07ae4346c88467476796cef921.Models

<div class="reference-card">
    <div class="card-header">
        <h4>Reference @(Index + 1)</h4>
