@code {
    [Parameter] public Reference Ref { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<int> OnRemove { get; set; }
    [Parameter] public EventCallback<(int, Reference)> OnChanged { get; set; }

    private async Task Update(string? name = null, string? relationship = null, string? email = null, string? phone = null)
    {
        var updated = Ref with
        {
            Name = name ?? Ref.Name,
            Relationship = relationship ?? Ref.Relationship,
            Email = email ?? Ref.Email,
            Phone = phone ?? Ref.Phone
        };
        await OnChanged.InvokeAsync((Index, updated));
    }
}

