                    <p>@r.Email | @r.Phone</p>
                </div>
            }
        </section>

        <section class="review-section">
            <div class="section-header">
                <h4>Cover Letter</h4>
                <button type="button" class="btn-edit" @onclick="() => OnEdit.InvokeAsync(4)">Edit</button>
