@page "/apply"
@rendermode InteractiveServer
@using sv_56351d07ae4346c88467476796cef921.Models
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-page">
    <h2>Job Application</h2>

    <StepIndicator CurrentStep="currentStep" CompletedSteps="completedSteps" OnStepClicked="GoToStep" />

    @switch (currentStep)
    {
        case 1:
            <PersonalInfoStep Model="@GetPersonalInfo()" OnNext="HandlePersonalNext"
                              IsValidating="isValidating" EmailError="@emailError" />
            break;
        case 2:
            <WorkHistoryStep Model="@GetWorkHistory()" OnNext="HandleWorkNext" OnBack="GoBack" />
            break;
        case 3:
            <ReferencesStep Model="@references" OnNext="HandleReferencesNext" OnBack="GoBack" />
            break;
        case 4:
            <CoverLetterStep CoverLetter="@coverLetter" OnNext="HandleCoverLetterNext" OnBack="GoBack" />
            break;
        case 5:
            <ReviewStep Personal="@GetPersonalInfo()" Work="@GetWorkHistory()"
                        References="@references" CoverLetter="@coverLetter"
                        OnEdit="GoToStep" OnSubmit="HandleSubmit"
                        IsSubmitting="isSubmitting" ApplicationId="@applicationId" />
            break;
    }
</div>

@code {
    private int currentStep = 1;
    private HashSet<int> completedSteps = new();

    // Mutable state
    private string fullName = "";
    private string email = "";
    private string phone = "";
    private string address = "";

    private List<WorkEntry> workEntries = new() { new WorkEntry("", "", DateTime.Today, null, "") };
    private List<Reference> references = new() { new Reference("", "", "", ""), new Reference("", "", "", "") };
    private string coverLetter = "";

    private bool isValidating;
    private string? emailError;
    private bool isSubmitting;
    private int? applicationId;

    private PersonalInfo GetPersonalInfo() => new(fullName, email, phone, address);
    private WorkHistory GetWorkHistory() => new(workEntries.ToList());

    private async Task HandlePersonalNext(PersonalInfo info)
    {
        emailError = null;
        isValidating = true;
        StateHasChanged();

        var isValid = await ApplicationService.ValidateEmailAsync(info.Email);
        isValidating = false;

        if (!isValid)
        {
            emailError = "Email address could not be validated.";
            return;
        }

        fullName = info.FullName;
        email = info.Email;
        phone = info.Phone;
        address = info.Address;

        completedSteps.Add(1);
        currentStep = 2;
    }

    private void HandleWorkNext(WorkHistory work)
    {
        workEntries = work.Entries.ToList();
        completedSteps.Add(2);
        currentStep = 3;
    }

    private void HandleReferencesNext(List<Reference> refs)
    {
        references = refs;
        completedSteps.Add(3);
        currentStep = 4;
    }

    private void HandleCoverLetterNext(string text)
    {
        coverLetter = text;
        completedSteps.Add(4);
        currentStep = 5;
    }

    private async Task HandleSubmit()
    {
        isSubmitting = true;
        StateHasChanged();

        var application = new JobApplication(
            GetPersonalInfo(),
            GetWorkHistory(),
            references,
            coverLetter
        );

        applicationId = await ApplicationService.SubmitApplicationAsync(application);
        isSubmitting = false;
    }

    private void GoToStep(int step)
    {
        currentStep = step;
    }

    private void GoBack()
    {
        if (currentStep > 1)
            currentStep--;
    }
}

.apply-page {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem;
}

/* Step Indicator */
.step-indicator {
    display: flex;
    justify-content: space-between;
    margin-bottom: 2rem;
    padding: 1rem 0;
}

.step-indicator .step {
    display: flex;
    flex-direction: column;
    align-items: center;
    flex: 1;
    cursor: default;
}

.step-indicator .step.completed {
    cursor: pointer;
}

.step-indicator .step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    border: 2px solid #ccc;
    margin-bottom: 0.5rem;
    font-weight: bold;
}

.step-indicator .step.active .step-circle {
    background-color: #0d6efd;
    color: white;
    border-color: #0d6efd;
}

.step-indicator .step.completed .step-circle {
    background-color: #198754;
    color: white;
    border-color: #198754;
}

.step-indicator .step.future .step-circle {
    opacity: 0.5;
}

.step-indicator .step-label {
    font-size: 0.8rem;
    text-align: center;
}

.step-indicator .step.active .step-label {
    font-weight: bold;
    color: #0d6efd;
}

.step-indicator .step.future .step-label {
    opacity: 0.5;
}

/* Form styles */
.step-content {
    background: #f8f9fa;
    border-radius: 8px;
    padding: 2rem;
}

.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.25rem;
    font-weight: 500;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="tel"],
.form-group input[type="date"],
.form-group textarea {
    width: 100%;
    padding: 0.5rem;
    border: 1px solid #dee2e6;
    border-radius: 4px;
    font-size: 1rem;
}

.form-group textarea {
    resize: vertical;
    min-height: 100px;
}

/* Buttons */
.step-buttons {
    display: flex;
    gap: 1rem;
    margin-top: 1.5rem;
    justify-content: flex-end;
}

.btn-next, .btn-submit {
    padding: 0.5rem 1.5rem;
    background-color: #0d6efd;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 1rem;
}

.btn-next:hover, .btn-submit:hover {
    background-color: #0b5ed7;
}

.btn-back {
    padding: 0.5rem 1.5rem;
    background-color: #6c757d;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 1rem;
}

.btn-add {
    padding: 0.4rem 1rem;
    background-color: #198754;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    margin-top: 0.5rem;
}

.btn-remove {
    padding: 0.25rem 0.75rem;
    background-color: #dc3545;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.85rem;
}

.btn-edit {
    padding: 0.2rem 0.6rem;
    background: none;
    border: 1px solid #0d6efd;
    color: #0d6efd;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.85rem;
}

/* Cards */
.work-entry-card, .reference-card {
    border: 1px solid #dee2e6;
    border-radius: 6px;
    padding: 1rem;
    margin-bottom: 1rem;
    background: white;
}

.card-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
}

.card-header h4 {
    margin: 0;
}

/* Validation */
.error {
    color: #dc3545;
    font-size: 0.9rem;
    margin: 0.25rem 0;
}

.validation-errors {
    margin-bottom: 1rem;
}

.char-count {
    font-size: 0.85rem;
    color: #6c757d;
    margin-top: 0.25rem;
}

/* Review */
.review-section {
    margin-bottom: 1.5rem;
    padding-bottom: 1rem;
    border-bottom: 1px solid #dee2e6;
}

.section-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.5rem;
}

.section-header h4 {
    margin: 0;
}

.review-entry {
    margin-left: 1rem;
    margin-bottom: 0.75rem;
}

.cover-letter-text {
    white-space: pre-wrap;
}

.confirmation {
    text-align: center;
    padding: 2rem;
}

.confirmation h4 {
    color: #198754;
}

button:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

