 @page "/apply"
 @rendermode InteractiveServer
 @using sv_56351d07ae4346c88467476796cef921.Models
 @inject IApplicationService ApplicationService

 <PageTitle>Job Application</PageTitle>

 <div class="apply-page">
     <h2>Job Application</h2>

     <StepIndicator CurrentStep="currentStep" CompletedSteps="completedSteps" OnStepClicked="GoToStep" />

     @switch (currentStep)
     {
         case 1:
             <PersonalInfoStep Model="@GetPersonalInfo()" OnNext="HandlePersonalNext"
                               IsValidating="isValidating" EmailError="@emailError" />
             break;
         case 2:
             <WorkHistoryStep Model="@GetWorkHistory()" OnNext="HandleWorkNext" OnBack="GoBack" />
             break;
         case 3:
             <ReferencesStep Model="@references" OnNext="HandleReferencesNext" OnBack="GoBack" />
             break;
         case 4:
             <CoverLetterStep CoverLetter="@coverLetter" OnNext="HandleCoverLetterNext" OnBack="GoBack" />
             break;
         case 5:
             <ReviewStep Personal="@GetPersonalInfo()" Work="@GetWorkHistory()"
                         References="@references" CoverLetter="@coverLetter"
                         OnEdit="GoToStep" OnSubmit="HandleSubmit"
                         IsSubmitting="isSubmitting" ApplicationId="@applicationId" />
             break;
     }
 </div>

 @code {
     private int currentStep = 1;
     private HashSet<int> completedSteps = new();

     // Mutable state
     private string fullName = "";
     private string email = "";
     private string phone = "";
     private string address = "";

     private List<WorkEntry> workEntries = new() { new WorkEntry("", "", DateTime.Today, null, "") };
     private List<Reference> references = new() { new Reference("", "", "", ""), new Reference("", "", "", "") };
     private string coverLetter = "";

     private bool isValidating;
     private string? emailError;
     private bool isSubmitting;
     private int? applicationId;

     private PersonalInfo GetPersonalInfo() => new(fullName, email, phone, address);
     private WorkHistory GetWorkHistory() => new(workEntries.ToList());

     private async Task HandlePersonalNext(PersonalInfo info)
     {
         emailError = null;
         isValidating = true;
         StateHasChanged();

         var isValid = await ApplicationService.ValidateEmailAsync(info.Email);
         isValidating = false;

         if (!isValid)
         {
             emailError = "Email address could not be validated.";
             return;
         }

         fullName = info.FullName;
         email = info.Email;
         phone = info.Phone;
         address = info.Address;

         completedSteps.Add(1);
         currentStep = 2;
     }

     private void HandleWorkNext(WorkHistory work)
     {
         workEntries = work.Entries.ToList();
         completedSteps.Add(2);
         currentStep = 3;
     }

     private void HandleReferencesNext(List<Reference> refs)
     {
         references = refs;
         completedSteps.Add(3);
         currentStep = 4;
     }

     private void HandleCoverLetterNext(string text)
     {
         coverLetter = text;
         completedSteps.Add(4);
         currentStep = 5;
     }

     private async Task HandleSubmit()
     {
         isSubmitting = true;
         StateHasChanged();

         var application = new JobApplication(
             GetPersonalInfo(),
             GetWorkHistory(),
             references,
             coverLetter
         );

         applicationId = await ApplicationService.SubmitApplicationAsync(application);
         isSubmitting = false;
     }

     private void GoToStep(int step)
     {
         currentStep = step;
     }

     private void GoBack()
     {
         if (currentStep > 1)
             currentStep--;
     }
 }

